.share-btn {
  transition: all 0.3s ease;
  color: var(--sl-text-main);
  border-color: var(--sl-border);
}
.share-btn svg {
  vertical-align: middle;
}
.share-btn[data-platform="facebook"]:hover {
  background-color: #1877f2;
  color: white;
  border-color: #1877f2;
}
.share-btn[data-platform="twitter"]:hover {
  background-color: #1DA1F2;
  color: white;
  border-color: #1DA1F2;
}
.share-btn[data-platform="whatsapp"]:hover {
  background-color: #25D366;
  color: white;
  border-color: #25D366;
}
.share-btn[data-platform="email"]:hover {
  background-color: var(--sl-primary);
  color: white;
  border-color: var(--sl-primary);
}
.share-btn .badge {
  font-size: 0.7em;
  padding: 0.3em 0.5em;
  background-color: var(--sl-primary) !important;
  color: white !important;
}

variante_1.js:
document.addEventListener('DOMContentLoaded', () => {
  const shareButtons = document.querySelectorAll('.share-btn');
  const pageUrl = encodeURIComponent(window.location.href);
  const pageTitle = encodeURIComponent(document.title);

  shareButtons.forEach(button => {
    const platform = button.dataset.platform;
    let shareLink = '#';

    switch (platform) {
      case 'facebook':
        shareLink = `https://www.facebook.com/sharer/sharer.php?u=${pageUrl}`;
        break;
      case 'twitter':
        shareLink = `https://twitter.com/intent/tweet?url=${pageUrl}&text=${pageTitle}`;
        break;
      case 'whatsapp':
        shareLink = `https://api.whatsapp.com/send?text=${pageTitle}%20${pageUrl}`;
        break;
      case 'email':
        shareLink = `mailto:?subject=${pageTitle}&body=${pageTitle}%0A${pageUrl}`;
        break;
      default:
        shareLink = '#';
    }
    button.setAttribute('href', shareLink);
    button.setAttribute('target', '_blank');
    button.setAttribute('rel', 'noopener noreferrer');
  });
});

