variante_3.js:
document.addEventListener('DOMContentLoaded', () => {
  const shareBtn = document.getElementById('universalShareBtn');
  const shareFeedback = document.getElementById('shareFeedback');

  if (shareBtn) {
    shareBtn.addEventListener('click', async () => {
      const url = window.location.href;
      const title = document.title;

      if (navigator.share) {
        try {
          await navigator.share({
            title: title,
            url: url
          });
          // Opcional: Feedback de sucesso após o compartilhamento nativo
          // showFeedback('Compartilhado com sucesso!', 'success');
        } catch (error) {
          if (error.name !== 'AbortError') {
            console.error('Erro ao compartilhar:', error);
            showFeedback('Falha ao compartilhar. Tente novamente.', 'danger');
          }
          // AbortError significa que o usuário cancelou, não é um erro para mostrar ao usuário
        }
      } else {
        // Fallback para copiar para a área de transferência
        try {
          await navigator.clipboard.writeText(url);
          showFeedback('Link copiado para a área de transferência!', 'success');
        } catch (err) {
          console.error('Falha ao copiar o link:', err);
          showFeedback('Falha ao copiar o link. Por favor, copie manualmente.', 'danger');
        }
      }
    });
  }

  function showFeedback(message, type) {
    shareFeedback.textContent = message;
    shareFeedback.classList.remove('d-none', 'text-success', 'text-danger');
    shareFeedback.classList.add(`text-${type}`);
    setTimeout(() => {
      shareFeedback.classList.add('d-none');
    }, 3000);
  }
});
